import{t as e}from"./utils-COoNfFoj.js";var t={slug:`bootstrapped-giants`,influencerName:`Bootstrapped Giants`,influencerHandle:`@BootstrappedGiants`,influencerAvatarUrl:`${e}/bootstrapped-giants-avatar.png`,heroDescription:`To help identify and evaluate sponsors in a workflow I could control and improve over time.`,assetTitle:`Ad Sales Machine`,screenshotUrl:`${e}/bootstrapped-giants.png`,remixUrl:`https://www.perplexity.ai/computer/a/ad-sales-machine-Vu0qYUr1TDmmetUNPHZKJg`,promptTitle:`Try Bootstrapped Giants' prompt`,promptText:`Build me a dashboard-first app called Ad Sales Machine that helps me sell sponsors for my newsletter by sourcing high-fit prospects, managing them through a simple Kanban pipeline, and generating one-click email drafts (without sending them). Prioritize inbound and existing relationships first, then expand by identifying companies already sponsoring similar audiences, focusing on high-growth B2B SaaS with budget but minimal bureaucracy and targeting the right marketing decision-makers based on company size. The app should include a Command Center overview, a Kanban board (Suggestions → Get Contact + Draft → Draft Sent → In Conversation → Closed Won → Closed Lost), a public sponsor signup page, and a system to generate, review, approve, reject, and learn from leads over time. Each suggested sponsor should include a clear, scannable summary covering what they do, why they fit, source, sponsor evidence, business signals, outreach angle, and any concerns, with clickable links. When approved, the system should find the right contact and draft an email. The signup page should be simple and titled “Reach founders obsessed with AI tools,” collecting basic info and campaign context, with a CTA button that says “Tell Andrew.” Keep everything clean, visual, and lightweight—no HubSpot, no automated sending.`};export{t as default};
